    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08*P[1],2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1*P[2]/5,1.7],
