    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07*P[5]/13,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09*P[6]/17,1.9]
