  return[Math.min(255,(pal[i2][0]+(pal[i2+1][0]-pal[i2][0])*f)*boost)|0,Math.min(255,(pal[i2][1]+(pal[i2+1][1]-pal[i2][1])*f)*boost)|0,Math.min(255,(pal[i2][2]+(pal[i2+1][2]-pal[i2][2])*f)*boost)|0];
}
